import{_ as t,c as s,o,ah as p,ao as i,ap as a}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"슬퍼해도 괜찮습니다 — 하나님은 당신의 눈물을 병에 담아 두십니다","description":"반려동물을 잃고 우는 것은 믿음이 약한 게 아닙니다. 시편은 하나님이 우리의 눈물을 병에 담고 책에 기록하신다고 말합니다.","frontmatter":{"title":"슬퍼해도 괜찮습니다 — 하나님은 당신의 눈물을 병에 담아 두십니다","description":"반려동물을 잃고 우는 것은 믿음이 약한 게 아닙니다. 시편은 하나님이 우리의 눈물을 병에 담고 책에 기록하신다고 말합니다."},"headers":[],"relativePath":"ko/pets-in-heaven/permission-to-grieve.md","filePath":"ko/pets-in-heaven/permission-to-grieve.md"}'),n={name:"ko/pets-in-heaven/permission-to-grieve.md"};function l(c,e,r,h,m,d){return o(),s("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>「몇 달이 지났는데도 아직 울어요. 제가 강하지 못한 걸까요? 믿음이 작은 걸까요?」</p><p class="pl-quote-soft">성경은 눈물을 실패의 증거로 다룬 적이 없습니다. 오히려 반대입니다.</p></div><section class="pl-section"><h2>1. 하나님은 눈물을 병에 담아 두십니다</h2><blockquote><p><strong>시편 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>다윗은 깊은 고통 속에서 이렇게 썼습니다. 그는 하나님께 자기 눈물을 병에 담고 책에 기록해 달라고 구합니다. 고대에 눈물 병은 아주 귀한 수집품이었고, 「이 사람이 이것 때문에 울었다」는 증거였습니다.</p><p>이것은 이런 뜻입니다. <strong>당신의 눈물은 흘러 사라지는 것이 아닙니다.</strong> 한 방울도 낭비되지 않습니다. 그 아이를 위해 흘린 모든 눈물이 담기고 기록됩니다.</p><p>「내가 너무 많이 우는 건가」라고 생각될 때 기억하세요. 하나님께 그것은 소음이 아니라 기록입니다.</p></section><section class="pl-section"><h2>2. 하나님은 상한 마음에 가까이 오십니다 — 꾸짖지 않으십니다</h2><blockquote><p><strong>시편 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>시편 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>동사를 보세요. 그분은 <em>가까이 오시고</em>, <em>고치시고</em>, <em>싸매십니다</em>. 하나님께서 슬퍼하는 사람에게 가장 먼저 하시는 일은 정신 차리라고 요구하는 것이 아니라 걸어오시는 것입니다.</p><p>예수님도 짧은 한 문장을 남기셨습니다.</p><blockquote><p><strong>마태복음 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>「애통하는 자는 복이 있나니.」 슬퍼하는 사람은 꾸짖음을 받지 않고 복 있는 사람으로 선언됩니다. 위로가 오기 때문입니다. 「기운 내야지」가 아니라 「너는 위로를 받게 된다」입니다.</p></section><section class="pl-section"><h2>3. 슬픔은 사랑의 반대가 아니라, 계속되는 사랑입니다</h2><p>한 번도 사랑하지 않은 것을 위해 우리는 울지 않습니다. 이렇게 아픈 이유는 두 사람 사이에 정말 사랑이 있었기 때문입니다.</p><p>하나님은 상실 앞에서 우는 존재로 우리를 지으셨습니다. 예수님 자신도 나사로의 무덤 앞에서 우셨습니다(요한복음 11:35). 몇 분 뒤 그를 다시 살리실 것을 아시면서도 우셨습니다.</p><p>그러니 눈물에 대해 누구에게도 사과할 필요가 없습니다. 믿음이 부족한 게 아닙니다. 사랑 안에서 상처를 입은 것입니다.</p><p class="pl-quote-soft">원하신다면 이렇게 기도해 보세요:</p></section><div class="pl-quote"><p>「주님, 제가 몇 번이나 울었는지 아십니다.<br>빨리 괜찮아지라고 재촉하지 않으시고, 모든 눈물을 병에 담아 주셔서 감사합니다.<br>상한 마음 가까이 오시는 것처럼 저에게도 가까이 와 주세요.<br>저를 고치시고, 제가 그리워하는 그 아이도 돌보아 주세요.<br>오늘은 강해지고 싶지 않습니다. 그냥 안아 주세요. 아멘.」</p></div><section class="pl-section"><h2>지금 스스로를 위해 할 수 있는 네 가지</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>감정이 가장 클 때 결정하지 마세요</h3><p>슬픔의 파도는 지나갑니다. 가장 아픈 순간에는 다음 5분을 버티면 충분합니다. 다른 일은 처리하지 마세요.</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>먼저 몸을 돌보세요</h3><p>물을 마시고, 뭘 좀 먹고, 잠깐 자세요. 애도는 몸을 소모시키고, 배고픈 몸은 마음을 더 아프게 합니다.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>노트에 그 아이를 써 보세요</h3><p>예쁘게 쓰지 않아도 됩니다. 어떻게 당신을 깨웠는지, 가장 좋아했던 표정 하나를 적어 보세요. 그리움에 머물 자리를 주세요.</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>정말 이해하는 사람을 찾으세요</h3><p>동물을 위해 우는 일을 모두가 이해하지는 않지만, 이해하는 사람도 있습니다. 없다면 적어 두세요. 하나님은 읽으실 수 있습니다.</p></div></div></section><section class="pl-section"><h2>그날이 옵니다</h2><p>요한계시록은 언젠가 하나님이 친히 우리 눈에서 모든 눈물을 닦아 주시고, 다시 사망도 슬픔도 울부짖음도 아픔도 없을 것이라고 약속합니다(요한계시록 21:4). 그날 당신은 그 아이를 위해 흘린 모든 눈물이 선하신 하나님께 기억되고 응답되었다는 것을 알게 될 것입니다.</p><p>그때까지, 슬퍼할 허락을 스스로에게 주세요. 그것도 그 아이를 계속 사랑하는 방식입니다.</p><p><a href="/ko/pets-in-heaven/">← Pets in Heaven으로 돌아가기</a> ｜ 첫 번째 글: <a href="/ko/pets-in-heaven/will-i-see-my-pet-again">다시 만날 수 있을까요?</a></p></section><div class="pl-cta"><h2>오늘은 한 문장이면 충분합니다.</h2><p>PetLoss에는 안내 일기와, 가장 무거운 순간에 중심을 잡아 주는 말을 건네는 SOS 동반자가 있습니다. 계정도 업로드도 없이 완전히 오프라인으로.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store에서 다운로드</a></div><div class="pl-bible"><h3>말씀이 계속 곁에 있도록</h3><p>이 글의 모든 구절은 성경에서 왔습니다. 무지개 성경 위젯 앱으로 언제든 말씀을 읽고 매일 말씀 위젯을 설정해 보세요. 그리운 날들에 작은 등불이 되어 줄 것입니다.</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Rainbow Bible 홈 화면 위젯 — 2 Timothy 2:13" loading="lazy"><figcaption>매일 말씀을 홈 화면에</figcaption></figure><figure><img src="'+a+'" alt="Rainbow Bible — 하늘나라의 반려동물 주제, 마태복음 10:29-31" loading="lazy"><figcaption>「하늘나라의 반려동물」 주제로 전환해 읽기</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Store에서 무지개 성경 위젯 받기</a></div>',9)])])}const g=t(n,[["render",l]]);export{v as __pageData,g as default};
